using System.Collections;
using System.Reflection;
using System.Reflection.Emit;
using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Powers;

namespace CombatSolver;

internal static class PowerOnlySuffixProof
{
    private static readonly Type View = typeof(SimulatedCombatState).GetNestedType("ConcatenatedListenerView", BindingFlags.NonPublic)!;
    private static readonly ConstructorInfo Constructor = View.GetConstructors(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic).Single();
    private static readonly PropertyInfo Witness = View.GetProperty("HasNonPowerSuffix")!;
    private static readonly FieldInfo WitnessField = View.GetField("<HasNonPowerSuffix>k__BackingField", BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static readonly MethodInfo Models = typeof(SimulatedCombatState).GetMethod("RemapCachedModels", BindingFlags.Static | BindingFlags.NonPublic)!;
    private static readonly MethodInfo Suffix = typeof(SimulatedCombatState).GetMethod("RemapCachedSuffix", BindingFlags.Static | BindingFlags.NonPublic)!;
    private static readonly Func<IReadOnlyList<AbstractModel>, PredictionForkContext, IReadOnlyList<AbstractModel>> Candidate = Models.CreateDelegate<Func<IReadOnlyList<AbstractModel>, PredictionForkContext, IReadOnlyList<AbstractModel>>>();
    private static long _calls, _suffixCalls, _fastSuffixCalls, _fastSlots, _mapped;

    private static IReadOnlyList<AbstractModel> Join(IReadOnlyList<AbstractModel> a, IReadOnlyList<AbstractModel> b, bool witness = false)
        => (IReadOnlyList<AbstractModel>)Constructor.Invoke([a, b, witness]);
    private static bool IsWitness(IReadOnlyList<AbstractModel> source) => (bool)Witness.GetValue(source)!;
    private static IReadOnlyList<AbstractModel> Original(IReadOnlyList<AbstractModel> source, PredictionForkContext context)
    {
        if (source is ISegmentedModelList view && source.GetType() == View)
        {
            var a = Original(view.Prefix, context); var b = Original(view.Suffix, context);
            return ReferenceEquals(a, view.Prefix) && ReferenceEquals(b, view.Suffix) ? source : Join(a, b);
        }
        AbstractModel[]? result = null;
        for (int i = 0; i < source.Count; i++)
        {
            AbstractModel mapped = context.RemapOrSelf(source[i]);
            if (ReferenceEquals(mapped, source[i])) continue;
            result ??= source.ToArray(); result[i] = mapped;
        }
        return result ?? source;
    }
    private static void CheckActual(IReadOnlyList<AbstractModel> source, PredictionForkContext context, IReadOnlyList<AbstractModel> result)
    {
        if (source.Count != result.Count) throw new InvalidOperationException("Actual listener count differs.");
        bool changed = false;
        for (int i = 0; i < source.Count; i++)
        {
            AbstractModel expected = context.RemapOrSelf(source[i]);
            if (!ReferenceEquals(expected, result[i])) throw new InvalidOperationException("Actual listener identity/order differs.");
            if (!ReferenceEquals(expected, source[i])) { changed = true; Interlocked.Increment(ref _mapped); }
        }
        if (!changed && !ReferenceEquals(source, result)) throw new InvalidOperationException("Unchanged snapshot identity differs.");
        Interlocked.Increment(ref _calls);
    }
    private static void ObserveModels(IReadOnlyList<AbstractModel> source, PredictionForkContext context, IReadOnlyList<AbstractModel> __result)
        => CheckActual(source, context, __result);
    private static void ObserveSuffix(object view, PredictionForkContext context, IReadOnlyList<AbstractModel> __result)
    {
        var joined = (ISegmentedModelList)view;
        CheckActual(joined.Suffix, context, __result);
        Interlocked.Increment(ref _suffixCalls);
        if ((bool)Witness.GetValue(view)! && context.HasOnlyPowerModelSources
            && (joined.Suffix.GetType() == typeof(List<AbstractModel>) || joined.Suffix.GetType() == typeof(AbstractModel[])))
        { Interlocked.Increment(ref _fastSuffixCalls); Interlocked.Add(ref _fastSlots, joined.Suffix.Count); }
    }
    internal static IDisposable VerifyAndObserve(CombatState live, CombatPredictionSimulator parent, Player player,
        Func<CombatPredictionSimulator, string> stamp, Action<string> record)
    {
        string parentBefore = stamp(parent), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        CardModel card = ModelDb.Card<StrikeIronclad>(); PowerModel power = ModelDb.Power<StrengthPower>();
        AbstractModel clonePower = (AbstractModel)RuntimeHelpers.GetUninitializedObject(power.GetType());
        AbstractModel cloneCard = (AbstractModel)RuntimeHelpers.GetUninitializedObject(card.GetType());
        CardModel unknown = Unknown();
        AbstractModel[] models = [.. ModelDb.All, unknown];
        int metadata = 0, comparisons = 0;
        foreach (AbstractModel model in models)
        {
            using PredictionForkContext context = new();
            context.Register<object>(model, new object());
            if (context.HasOnlyPowerModelSources != (model is PowerModel))
                throw new InvalidOperationException("Actual source CLR classification differs.");
            metadata++;
        }
        foreach (int count in new[] { 0, 64, 128 })
        {
            using PredictionForkContext context = new();
            for (int i = 0; i < count; i++) context.Register(new object(), new object());
            context.Register<object>(new object(), card);
            context.Register<object>(card, card);
            context.Register<object>(power, clonePower);
            context.Register<AbstractModel>(power, clonePower);
            if (!context.HasOnlyPowerModelSources) throw new InvalidOperationException("Target/generic/self registration altered source classification.");
            context.Register<object>(null!, card);
            if (context.HasOnlyPowerModelSources) throw new InvalidOperationException("Null mapping was excluded.");
        }
        foreach (int shape in Enumerable.Range(0, 6))
        foreach (int mode in Enumerable.Range(0, 6))
        {
            using PredictionForkContext a = new(), b = new();
            void Seed(PredictionForkContext c)
            {
                for (int i = 0; i < 128; i++) c.Register(new object(), new object());
                if (mode == 1) c.Register<object>(power, clonePower);
                if (mode == 2) c.Register<object>(card, cloneCard);
                if (mode == 3) c.Register<object>(null!, card);
                if (mode == 4) c.Register<AbstractModel>(card, clonePower);
            }
            Seed(a); Seed(b); GetterList? ga, gb;
            IReadOnlyList<AbstractModel> Build(PredictionForkContext c, out GetterList? getter)
            {
                AbstractModel[] values = [card, unknown, null!]; getter = null;
                IReadOnlyList<AbstractModel> suffix = values;
                if (shape == 1) suffix = values.ToList();
                if (shape == 2) suffix = new CardModel[] { card, unknown };
                if (shape >= 3)
                {
                    getter = new GetterList(values, mode == 5 ? () => c.Register<object>(card, cloneCard) : null);
                    suffix = shape == 3 ? getter : shape == 4 ? Join([], getter) : new DerivedList(values);
                }
                return Join([power], suffix, witness: true);
            }
            var sa = Build(a, out ga); var sb = Build(b, out gb);
            var expected = Original(sa, a); var actual = Candidate(sb, b);
            if (!expected.SequenceEqual(actual, ReferenceEqualityComparer.Instance)
                || ReferenceEquals(expected, sa) != ReferenceEquals(actual, sb))
                throw new InvalidOperationException("Witnessed/unknown/null/mixed suffix differs.");
            if (ga != null && gb != null && (ga.CountReads != gb.CountReads || ga.IndexReads != gb.IndexReads))
                throw new InvalidOperationException("Unknown access prefix differs.");
            if (!ReferenceEquals(((ISegmentedModelList)actual).Suffix, ((ISegmentedModelList)sb).Suffix) && IsWitness(actual))
                throw new InvalidOperationException("Changed suffix retained the no-Power witness.");
            // A mapped Card -> Power result must lose its witness before a later Power-only context.
            if (mode == 4)
            {
                using PredictionForkContext next = new(); next.Register<object>(clonePower, power);
                if (!Original(actual, next).SequenceEqual(Candidate(actual, next), ReferenceEqualityComparer.Instance))
                    throw new InvalidOperationException("Descendant remapping reused a stale witness.");
            }
            comparisons++;
        }
        using (PredictionForkContext a = new())
        using (PredictionForkContext b = new())
        {
            GetterList ga = new([card, unknown], null, 2), gb = new([card, unknown], null, 2);
            var sa = Join([], ga, true); var sb = Join([], gb, true);
            foreach (bool candidate in new[] { false, true })
            {
                try { _ = candidate ? Candidate(sb, b) : Original(sa, a); throw new InvalidOperationException("Missing getter error."); }
                catch (InvalidOperationException error) when (error.Message == "getter-injected") { }
            }
            if (ga.CountReads != gb.CountReads || ga.IndexReads != gb.IndexReads)
                throw new InvalidOperationException("Getter exception prefix differs.");
        }
        var modelsPost = typeof(PowerOnlySuffixProof).GetMethod(nameof(ObserveModels), BindingFlags.NonPublic | BindingFlags.Static)!;
        var suffixPost = typeof(PowerOnlySuffixProof).GetMethod(nameof(ObserveSuffix), BindingFlags.NonPublic | BindingFlags.Static)!;
        Harmony harmony = new("CombatSolver.Tests.PowerOnlySuffix");
        harmony.Patch(Models, postfix: new HarmonyMethod(modelsPost)); harmony.Patch(Suffix, postfix: new HarmonyMethod(suffixPost));
        try
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            CombatPredictionSimulator seed = parent.Fork();
            var combat = (SimulatedCombatState)seed.State.CombatState;
            combat.Apply<StrengthPower>(player.Creature, 2, player.Creature);
            if (!CombatBeamSolver.SettleReplayActionBoundary(seed, combat))
                throw new InvalidOperationException("Power fixture opened an unexpected boundary.");
            _ = combat.IterateHookListeners().ToArray();
            string seedBefore = stamp(seed);
            var field = typeof(SimulatedCombatState).GetField("_baseHookListeners", BindingFlags.Instance | BindingFlags.NonPublic)!;
            var baseView = (IReadOnlyList<AbstractModel>)field.GetValue(combat)!;
            if (baseView.GetType() != View || !IsWitness(baseView)) throw new InvalidOperationException("Native typed suffix witness missing.");
            CombatPredictionSimulator actual = seed.Fork();
            WitnessField.SetValue(baseView, false);
            CombatPredictionSimulator reference;
            try { reference = seed.Fork(); }
            finally { WitnessField.SetValue(baseView, true); }
            if (stamp(reference) != stamp(actual)) throw new InvalidOperationException("Witnessed/unwitnessed native forks differ.");
            Parallel.For(0, 16, i =>
            {
                using IDisposable isolation = SimulationNotificationIsolation.Enter(); CombatPredictionSimulator child;
                lock (seed) child = seed.Fork();
                if (stamp(child) != seedBefore) throw new InvalidOperationException("Power child complete state/history/RNG differs.");
                var state = (SimulatedCombatState)child.State.CombatState;
                if (ReferenceEquals(state.GetPower<StrengthPower>(player.Creature), combat.GetPower<StrengthPower>(player.Creature)))
                    throw new InvalidOperationException("Power receiver was not cloned.");
                child.State.GetPlayerCombatState(player).Hand.Cards[0].MutablePreview.BaseReplayCount = i + 1;
                _ = state.IterateHookListeners().ToArray();
                if (stamp(child.Fork()) != stamp(child)) throw new InvalidOperationException("Invalidated COW descendant differs.");
            });
            if (stamp(seed) != seedBefore || stamp(parent) != parentBefore || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
                throw new InvalidOperationException("Witness changed seed/parent/live.");
            record("PowerOnlySuffix:SourceOracle:" + JsonSerializer.Serialize(new { metadata, comparisons, shapes=6, modes=6,
                parallelForks=16, scope="Actual CLR source aliases/targets/null; changed-suffix witness removal; two-generation Power remap; exact arrays/lists, covariance/derived/unknown access fallback; error prefix; native witnessed/unwitnessed full state/history/RNG; actual cloned Power; card invalidation; parent/live isolation." }));
            return new Scope(harmony, modelsPost, suffixPost, record);
        }
        catch { harmony.Unpatch(Models, modelsPost); harmony.Unpatch(Suffix, suffixPost); throw; }
    }
    private sealed class GetterList(AbstractModel[] values, Action? onRead, int throwAt = -1) : IReadOnlyList<AbstractModel>
    {
        internal int CountReads, IndexReads;
        public int Count { get { CountReads++; return values.Length; } }
        public AbstractModel this[int index] { get { IndexReads++; if (IndexReads == throwAt) throw new InvalidOperationException("getter-injected"); onRead?.Invoke(); return values[index]; } }
        public IEnumerator<AbstractModel> GetEnumerator() { for (int i=0; i<Count; i++) yield return this[i]; }
        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
    }
    private sealed class DerivedList(IEnumerable<AbstractModel> values) : List<AbstractModel>(values);
    private sealed class Scope(Harmony harmony, MethodInfo modelsPost, MethodInfo suffixPost, Action<string> record) : IDisposable
    {
        public void Dispose()
        {
            harmony.Unpatch(Models, modelsPost); harmony.Unpatch(Suffix, suffixPost);
            if (_fastSuffixCalls == 0 || _mapped == 0) throw new InvalidOperationException("Actual fast suffix and mapped receiver were not both covered.");
            record("PowerOnlySuffix:ActualOracle:" + JsonSerializer.Serialize(new { calls=_calls, suffixCalls=_suffixCalls,
                fastSuffixCalls=_fastSuffixCalls, fastSlots=_fastSlots, mappedSlots=_mapped }));
        }
    }
    private static CardModel Unknown()
    {
        var assembly = AssemblyBuilder.DefineDynamicAssembly(new AssemblyName("CombatSolver.Tests.PowerSuffix.Unknown"), AssemblyBuilderAccess.RunAndCollect);
        var type = assembly.DefineDynamicModule("Probe").DefineType("UnknownCard", TypeAttributes.Public | TypeAttributes.Sealed, typeof(CardModel));
        var constructor=type.DefineConstructor(MethodAttributes.Public, CallingConventions.Standard, Type.EmptyTypes);
        var il=constructor.GetILGenerator(); il.Emit(OpCodes.Ldnull); il.Emit(OpCodes.Throw);
        return (CardModel)RuntimeHelpers.GetUninitializedObject(type.CreateType()!);
    }
}

sources.native-types/OrbModel.cs:
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Godot;
using MegaCrit.Sts2.Core.Assets;
using MegaCrit.Sts2.Core.Audio.Debug;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Context;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Helpers;
using MegaCrit.Sts2.Core.Hooks;
using MegaCrit.Sts2.Core.HoverTips;
using MegaCrit.Sts2.Core.Localization;
using MegaCrit.Sts2.Core.Models.Orbs;
using MegaCrit.Sts2.Core.Random;

namespace MegaCrit.Sts2.Core.Models;

public abstract class OrbModel : AbstractModel
{
	public const string locTable = "orbs";

	private static readonly ModelId[] _validOrbs = new ModelId[5]
	{
		ModelDb.GetId<LightningOrb>(),
		ModelDb.GetId<FrostOrb>(),
		ModelDb.GetId<DarkOrb>(),
		ModelDb.GetId<PlasmaOrb>(),
		ModelDb.GetId<GlassOrb>()
	};

	private OrbModel _canonicalInstance;

	private Player? _owner;

	public abstract decimal PassiveVal { get; }

	public abstract decimal EvokeVal { get; }

	/// <summary>
	/// Set to true when this is removed from a player's orb queue.
	/// </summary>
	public bool HasBeenRemovedFromState { get; private set; }

	public LocString Title => new LocString("orbs", base.Id.Entry + ".title");

	public LocString Description => new LocString("orbs", base.Id.Entry + ".description");

	public bool HasSmartDescription => LocString.Exists("orbs", SmartDescriptionLocKey);

	private string SmartDescriptionLocKey => base.Id.Entry + ".smartDescription";

	/// <summary>
	/// NOTE: Unlike other models' DynamicDescription, this doesn't include any variables. Someone should probably do that
	/// but it's a bit larger of a refactor than I want to do right now
	/// </summary>
	public LocString SmartDescription
	{
		get
		{
			if (!HasSmartDescription)
			{
				return Description;
			}
			return new LocString("orbs", base.Id.Entry + ".smartDescription");
		}
	}

	private string DebugPassiveSfx => base.Id.Entry.ToLowerInvariant() + "_passive.mp3";

	private string DebugEvokeSfx => base.Id.Entry.ToLowerInvariant() + "_evoke.mp3";

	private string DebugChannelSfx => base.Id.Entry.ToLowerInvariant() + "_channel.mp3";

	protected virtual string PassiveSfx => "";

	protected virtual string EvokeSfx => "";

	protected virtual string ChannelSfx => "";

	public static HoverTip EmptySlotHoverTipHoverTip => new HoverTip(new LocString("orbs", "EMPTY_SLOT.title"), new LocString("orbs", "EMPTY_SLOT.description"));

	public HoverTip DumbHoverTip => new HoverTip(this, Description);

	protected virtual IEnumerable<IHoverTip> ExtraHoverTips => Array.Empty<IHoverTip>();

	public IEnumerable<IHoverTip> HoverTips
	{
		get
		{
			List<IHoverTip> list = ExtraHoverTips.ToList();
			if (HasSmartDescription && base.IsMutable)
			{
				LocString smartDescription = SmartDescription;
				smartDescription.Add("energyPrefix", Owner.Character.CardPool.Title);
				smartDescription.Add("Passive", PassiveVal);
				smartDescription.Add("Evoke", EvokeVal);
				list.Add(new HoverTip(this, smartDescription));
			}
			else
			{
				list.Add(DumbHoverTip);
			}
			return list;
		}
	}

	private string IconPath => ImageHelper.GetImagePath("orbs/" + base.Id.Entry.ToLowerInvariant() + ".png");

	private string SpritePath => SceneHelper.GetScenePath("orbs/orb_visuals/" + base.Id.Entry.ToLowerInvariant());

	public CompressedTexture2D Icon => PreloadManager.Cache.GetCompressedTexture2D(IconPath);

	public abstract Color DarkenedColor { get; }

	private OrbModel CanonicalInstance
	{
		get
		{
			if (!base.IsMutable)
			{
				return this;
			}
			return _canonicalInstance;
		}
		set
		{
			AssertMutable();
			_canonicalInstance = value;
		}
	}

	public Player Owner
	{
		get
		{
			AssertMutable();
			return _owner;
		}
		set
		{
			AssertMutable();
			if (_owner != null && value != null && value != _owner)
			{
				throw new InvalidOperationException("Card " + base.Id.Entry + " already has an owner.");
			}
			_owner = value;
		}
	}

	/// <summary>
	/// Get the CombatState of the orb's owner.
	/// Will never be null, since orbs are combat-only.
	/// </summary>
	public ICombatState CombatState => Owner.Creature.CombatState;

	public override bool ShouldReceiveCombatHooks => true;

	public IEnumerable<string> AssetPaths => new global::<>z__ReadOnlyArray<string>(new string[2] { IconPath, SpritePath });

	public event Action? PassiveActivated;

	public event Action<Creature[]>? EvokeActivated;

	public static OrbModel GetRandomOrb(Rng rng)
	{
		return ModelDb.GetById<OrbModel>(rng.NextItem(_validOrbs));
	}

	protected void PlayPassiveSfx()
	{
		if (PassiveSfx != "")
		{
			SfxCmd.Play(PassiveSfx);
		}
		else
		{
			NDebugAudioManager.Instance?.Play(DebugPassiveSfx);
		}
	}

	protected void PlayEvokeSfx()
	{
		if (EvokeSfx != "")
		{
			SfxCmd.Play(EvokeSfx);
		}
		else
		{
			NDebugAudioManager.Instance?.Play(DebugEvokeSfx);
		}
	}

	public void PlayChannelSfx()
	{
		if (ChannelSfx != "")
		{
			SfxCmd.Play(ChannelSfx);
		}
		else
		{
			NDebugAudioManager.Instance?.Play(DebugChannelSfx);
		}
	}

	public Node2D CreateSprite()
	{
		return PreloadManager.Cache.GetScene(SpritePath).Instantiate<Node2D>(PackedScene.GenEditState.Disabled);
	}

	public OrbModel ToMutable(int initialAmount = 0)
	{
		AssertCanonical();
		OrbModel orbModel = (OrbModel)MutableClone();
		orbModel.CanonicalInstance = this;
		return orbModel;
	}

	protected void ActivatePassive()
	{
		this.PassiveActivated?.Invoke();
	}

	public void ActivateEvoke(Creature[] targets)
	{
		this.EvokeActivated?.Invoke(targets);
	}

	public virtual Task BeforeTurnEndOrbTrigger(PlayerChoiceContext choiceContext)
	{
		return Task.CompletedTask;
	}

	public virtual Task AfterTurnStartOrbTrigger(PlayerChoiceContext choiceContext)
	{
		return Task.CompletedTask;
	}

	/// <summary>
	/// Calculates the number of times an Orb's passive should trigger and performs it.
	/// </summary>
	public async Task TriggerPassive(PlayerChoiceContext choiceContext, Creature? target)
	{
		List<AbstractModel> modifyingModels;
		int triggerCount = Hook.ModifyOrbPassiveTriggerCount(Owner.Creature.CombatState, this, 1, out modifyingModels);
		await Hook.AfterModifyingOrbPassiveTriggerCount(Owner.Creature.CombatState, this, modifyingModels);
		for (int i = 0; i < triggerCount; i++)
		{
			await Passive(choiceContext, target);
			if (LocalContext.IsMe(Owner))
			{
				await Cmd.CustomScaledWait(0.1f, 0.25f);
			}
			else
			{
				await Cmd.Wait(0.05f);
			}
		}
	}

	/// <summary>
	/// CAREFUL: Should only be used if in special cases, since this skips the ModifyOrbPassiveTrigger.
	/// </summary>
	public virtual Task Passive(PlayerChoiceContext choiceContext, Creature? target)
	{
		return Task.CompletedTask;
	}

	public virtual Task<IEnumerable<Creature>> Evoke(PlayerChoiceContext playerChoiceContext)
	{
		return Task.FromResult((IEnumerable<Creature>)Array.Empty<Creature>());
	}

	protected decimal ModifyOrbValue(decimal result)
	{
		return Hook.ModifyOrbValue(Owner.Creature.CombatState, this, result);
	}

	protected override void AfterCloned()
	{
		base.AfterCloned();
		this.EvokeActivated = null;
		this.PassiveActivated = null;
	}

	public void RemoveInternal()
	{
		HasBeenRemovedFromState = true;
	}
}
