using System.Collections;
using System.Reflection;
using System.Reflection.Emit;
using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Powers;

namespace CombatSolver;

internal static class PowerOnlySuffixProof
{
    private static readonly Type View = typeof(SimulatedCombatState).GetNestedType("ConcatenatedListenerView", BindingFlags.NonPublic)!;
    private static readonly ConstructorInfo Constructor = View.GetConstructors(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic).Single();
    private static readonly PropertyInfo Witness = View.GetProperty("HasNonPowerSuffix")!;
    private static readonly FieldInfo WitnessField = View.GetField("<HasNonPowerSuffix>k__BackingField", BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static readonly MethodInfo Models = typeof(SimulatedCombatState).GetMethod("RemapCachedModels", BindingFlags.Static | BindingFlags.NonPublic)!;
    private static readonly MethodInfo Suffix = typeof(SimulatedCombatState).GetMethod("RemapCachedSuffix", BindingFlags.Static | BindingFlags.NonPublic)!;
    private static readonly Func<IReadOnlyList<AbstractModel>, PredictionForkContext, IReadOnlyList<AbstractModel>> Candidate = Models.CreateDelegate<Func<IReadOnlyList<AbstractModel>, PredictionForkContext, IReadOnlyList<AbstractModel>>>();
    private static long _calls, _suffixCalls, _fastSuffixCalls, _fastSlots, _mapped;

    private static IReadOnlyList<AbstractModel> Join(IReadOnlyList<AbstractModel> a, IReadOnlyList<AbstractModel> b, bool witness = false)
        => (IReadOnlyList<AbstractModel>)Constructor.Invoke([a, b, witness]);
    private static bool IsWitness(IReadOnlyList<AbstractModel> source) => (bool)Witness.GetValue(source)!;
    private static IReadOnlyList<AbstractModel> Original(IReadOnlyList<AbstractModel> source, PredictionForkContext context)
    {
        if (source is ISegmentedModelList view && source.GetType() == View)
        {
            var a = Original(view.Prefix, context); var b = Original(view.Suffix, context);
            return ReferenceEquals(a, view.Prefix) && ReferenceEquals(b, view.Suffix) ? source : Join(a, b);
        }
        AbstractModel[]? result = null;
        for (int i = 0; i < source.Count; i++)
        {
            AbstractModel mapped = context.RemapOrSelf(source[i]);
            if (ReferenceEquals(mapped, source[i])) continue;
            result ??= source.ToArray(); result[i] = mapped;
        }
        return result ?? source;
    }
    private static void CheckActual(IReadOnlyList<AbstractModel> source, PredictionForkContext context, IReadOnlyList<AbstractModel> result)
    {
        if (source.Count != result.Count) throw new InvalidOperationException("Actual listener count differs.");
        bool changed = false;
        for (int i = 0; i < source.Count; i++)
        {
            AbstractModel expected = context.RemapOrSelf(source[i]);
            if (!ReferenceEquals(expected, result[i])) throw new InvalidOperationException("Actual listener identity/order differs.");
            if (!ReferenceEquals(expected, source[i])) { changed = true; Interlocked.Increment(ref _mapped); }
        }
        if (!changed && !ReferenceEquals(source, result)) throw new InvalidOperationException("Unchanged snapshot identity differs.");
        Interlocked.Increment(ref _calls);
    }
    private static void ObserveModels(IReadOnlyList<AbstractModel> source, PredictionForkContext context, IReadOnlyList<AbstractModel> __result)
        => CheckActual(source, context, __result);
    private static void ObserveSuffix(object view, PredictionForkContext context, IReadOnlyList<AbstractModel> __result)
    {
        var joined = (ISegmentedModelList)view;
        CheckActual(joined.Suffix, context, __result);
        Interlocked.Increment(ref _suffixCalls);
        if ((bool)Witness.GetValue(view)! && context.HasOnlyPowerModelSources
            && (joined.Suffix.GetType() == typeof(List<AbstractModel>) || joined.Suffix.GetType() == typeof(AbstractModel[])))
        { Interlocked.Increment(ref _fastSuffixCalls); Interlocked.Add(ref _fastSlots, joined.Suffix.Count); }
    }
    internal static IDisposable VerifyAndObserve(CombatState live, CombatPredictionSimulator parent, Player player,
        Func<CombatPredictionSimulator, string> stamp, Action<string> record)
    {
        string parentBefore = stamp(parent), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        CardModel card = ModelDb.Card<StrikeIronclad>(); PowerModel power = ModelDb.Power<StrengthPower>();
        AbstractModel clonePower = (AbstractModel)RuntimeHelpers.GetUninitializedObject(power.GetType());
        AbstractModel cloneCard = (AbstractModel)RuntimeHelpers.GetUninitializedObject(card.GetType());
        CardModel unknown = Unknown();
        AbstractModel[] models = [.. ModelDb.All, unknown];
        int metadata = 0, comparisons = 0;
        foreach (AbstractModel model in models)
        {
            using PredictionForkContext context = new();
            context.Register<object>(model, new object());
            if (context.HasOnlyPowerModelSources != (model is PowerModel))
                throw new InvalidOperationException("Actual source CLR classification differs.");
            metadata++;
        }
        foreach (int count in new[] { 0, 64, 128 })
        {
            using PredictionForkContext context = new();
            for (int i = 0; i < count; i++) context.Register(new object(), new object());
            context.Register<object>(new object(), card);
            context.Register<object>(card, card);
            context.Register<object>(power, clonePower);
            context.Register<AbstractModel>(power, clonePower);
            if (!context.HasOnlyPowerModelSources) throw new InvalidOperationException("Target/generic/self registration altered source classification.");
            context.Register<object>(null!, card);
            if (context.HasOnlyPowerModelSources) throw new InvalidOperationException("Null mapping was excluded.");
        }
        foreach (int shape in Enumerable.Range(0, 6))
        foreach (int mode in Enumerable.Range(0, 6))
        {
            using PredictionForkContext a = new(), b = new();
            void Seed(PredictionForkContext c)
            {
                for (int i = 0; i < 128; i++) c.Register(new object(), new object());
                if (mode == 1) c.Register<object>(power, clonePower);
                if (mode == 2) c.Register<object>(card, cloneCard);
                if (mode == 3) c.Register<object>(null!, card);
                if (mode == 4) c.Register<AbstractModel>(card, clonePower);
            }
            Seed(a); Seed(b); GetterList? ga, gb;
            IReadOnlyList<AbstractModel> Build(PredictionForkContext c, out GetterList? getter)
            {
                AbstractModel[] values = [card, unknown, null!]; getter = null;
                IReadOnlyList<AbstractModel> suffix = values;
                if (shape == 1) suffix = values.ToList();
                if (shape == 2) suffix = new CardModel[] { card, unknown };
                if (shape >= 3)
                {
                    getter = new GetterList(values, mode == 5 ? () => c.Register<object>(card, cloneCard) : null);
                    suffix = shape == 3 ? getter : shape == 4 ? Join([], getter) : new DerivedList(values);
                }
                return Join([power], suffix, witness: true);
            }
            var sa = Build(a, out ga); var sb = Build(b, out gb);
            var expected = Original(sa, a); var actual = Candidate(sb, b);
            if (!expected.SequenceEqual(actual, ReferenceEqualityComparer.Instance)
                || ReferenceEquals(expected, sa) != ReferenceEquals(actual, sb))
                throw new InvalidOperationException("Witnessed/unknown/null/mixed suffix differs.");
            if (ga != null && gb != null && (ga.CountReads != gb.CountReads || ga.IndexReads != gb.IndexReads))
                throw new InvalidOperationException("Unknown access prefix differs.");
            if (!ReferenceEquals(((ISegmentedModelList)actual).Suffix, ((ISegmentedModelList)sb).Suffix) && IsWitness(actual))
                throw new InvalidOperationException("Changed suffix retained the no-Power witness.");
            // A mapped Card -> Power result must lose its witness before a later Power-only context.
            if (mode == 4)
            {
                using PredictionForkContext next = new(); next.Register<object>(clonePower, power);
                if (!Original(actual, next).SequenceEqual(Candidate(actual, next), ReferenceEqualityComparer.Instance))
                    throw new InvalidOperationException("Descendant remapping reused a stale witness.");
            }
            comparisons++;
        }
        using (PredictionForkContext a = new())
        using (PredictionForkContext b = new())
        {
            GetterList ga = new([card, unknown], null, 2), gb = new([card, unknown], null, 2);
            var sa = Join([], ga, true); var sb = Join([], gb, true);
            foreach (bool candidate in new[] { false, true })
            {
                try { _ = candidate ? Candidate(sb, b) : Original(sa, a); throw new InvalidOperationException("Missing getter error."); }
