        var suffixPost = typeof(PowerOnlySuffixProof).GetMethod(nameof(ObserveSuffix), BindingFlags.NonPublic | BindingFlags.Static)!;
        Harmony harmony = new("CombatSolver.Tests.PowerOnlySuffix");
        harmony.Patch(Models, postfix: new HarmonyMethod(modelsPost)); harmony.Patch(Suffix, postfix: new HarmonyMethod(suffixPost));
        try
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            CombatPredictionSimulator seed = parent.Fork();
            var combat = (SimulatedCombatState)seed.State.CombatState;
            combat.Apply<StrengthPower>(player.Creature, 2, player.Creature);
            _ = combat.IterateHookListeners().ToArray();
            string seedBefore = stamp(seed);
            var field = typeof(SimulatedCombatState).GetField("_baseHookListeners", BindingFlags.Instance | BindingFlags.NonPublic)!;
            var baseView = (IReadOnlyList<AbstractModel>)field.GetValue(combat)!;
            if (baseView.GetType() != View || !IsWitness(baseView)) throw new InvalidOperationException("Native typed suffix witness missing.");
            CombatPredictionSimulator actual = seed.Fork();
            WitnessField.SetValue(baseView, false);
            CombatPredictionSimulator reference;
            try { reference = seed.Fork(); }
            finally { WitnessField.SetValue(baseView, true); }
            if (stamp(reference) != stamp(actual)) throw new InvalidOperationException("Witnessed/unwitnessed native forks differ.");
            Parallel.For(0, 16, i =>
            {
                using IDisposable isolation = SimulationNotificationIsolation.Enter(); CombatPredictionSimulator child;
                lock (seed) child = seed.Fork();
                if (stamp(child) != seedBefore) throw new InvalidOperationException("Power child complete state/history/RNG differs.");
                var state = (SimulatedCombatState)child.State.CombatState;
                if (ReferenceEquals(state.GetPower<StrengthPower>(player.Creature), combat.GetPower<StrengthPower>(player.Creature)))
                    throw new InvalidOperationException("Power receiver was not cloned.");
                child.State.GetPlayerCombatState(player).Hand.Cards[0].MutablePreview.BaseReplayCount = i + 1;
                _ = state.IterateHookListeners().ToArray();
                if (stamp(child.Fork()) != stamp(child)) throw new InvalidOperationException("Invalidated COW descendant differs.");
            });
            if (stamp(seed) != seedBefore || stamp(parent) != parentBefore || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
                throw new InvalidOperationException("Witness changed seed/parent/live.");
            record("PowerOnlySuffix:SourceOracle:" + JsonSerializer.Serialize(new { metadata, comparisons, shapes=6, modes=6,
                parallelForks=16, scope="Actual CLR source aliases/targets/null; changed-suffix witness removal; two-generation Power remap; exact arrays/lists, covariance/derived/unknown access fallback; error prefix; native witnessed/unwitnessed full state/history/RNG; actual cloned Power; card invalidation; parent/live isolation." }));
            return new Scope(harmony, modelsPost, suffixPost, record);
        }
        catch { harmony.Unpatch(Models, modelsPost); harmony.Unpatch(Suffix, suffixPost); throw; }
    }
    private sealed class GetterList(AbstractModel[] values, Action? onRead, int throwAt = -1) : IReadOnlyList<AbstractModel>
    {
        internal int CountReads, IndexReads;
        public int Count { get { CountReads++; return values.Length; } }
        public AbstractModel this[int index] { get { IndexReads++; if (IndexReads == throwAt) throw new InvalidOperationException("getter-injected"); onRead?.Invoke(); return values[index]; } }
