        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
    }
    private sealed class DerivedList(IEnumerable<AbstractModel> values) : List<AbstractModel>(values);
    private sealed class Scope(Harmony harmony, MethodInfo modelsPost, MethodInfo suffixPost, Action<string> record) : IDisposable
    {
        public void Dispose()
        {
            harmony.Unpatch(Models, modelsPost); harmony.Unpatch(Suffix, suffixPost);
            if (_fastSuffixCalls == 0 || _mapped == 0) throw new InvalidOperationException("Actual fast suffix and mapped receiver were not both covered.");
